package automation

import (
	"context"
	"errors"

	"go.uber.org/zap"
)

// settleFailedRunTask archives the hidden task generated by a definitively
// failed run, when every guard allows it.
//
// It runs only for a persisted terminal failed run with a bound task, only for
// the hidden automation_run origin, and never for a task still referenced by
// another run, the automation's continuation pointer, or a foreign automation.
// A live agent session is refused by the archiver rather than stopped, so a
// reply that raced the failure keeps the task. Everything else is best-effort
// and idempotent: an already-archived or missing task is success and any other
// error is logged for the startup pass to retry. The run row, its error
// message, and its transcript are never touched.
func (s *Service) settleFailedRunTask(ctx context.Context, run *AutomationRun) {
	if run == nil || s.taskArchiver == nil {
		return
	}
	if run.Status != RunStatusFailed || run.TaskID == "" {
		return
	}
	if !s.failedRunTaskOriginIsHidden(ctx, run.TaskID) {
		return
	}
	referenced, err := s.runTaskHasReferences(ctx, run, run.TaskID)
	if err != nil {
		s.logger.Warn("failed to check failed-run task references",
			zap.String("run_id", run.ID), zap.String("task_id", run.TaskID), zap.Error(err))
		return
	}
	if referenced {
		return
	}
	inUse, err := s.store.RunWorkspaceInUse(ctx, run.TaskID)
	if err != nil {
		s.logger.Warn("failed to check failed-run task liveness",
			zap.String("run_id", run.ID), zap.String("task_id", run.TaskID), zap.Error(err))
		return
	}
	if inUse {
		return
	}
	err = s.taskArchiver.ArchiveTaskIfIdle(ctx, run.TaskID)
	switch {
	case err == nil:
		s.logger.Info("archived the generated task of a failed automation run",
			zap.String("run_id", run.ID), zap.String("task_id", run.TaskID))
	case errorsIsAnyOf(err, ErrTaskAlreadyArchived, ErrTaskNotFound, ErrTaskActiveSessions):
		return
	default:
		s.logger.Warn("failed to archive the generated task of a failed automation run",
			zap.String("run_id", run.ID), zap.String("task_id", run.TaskID), zap.Error(err))
	}
}

// settleFailedRunTaskForTask settles the generated task of the newest failed
// run bound to a task. Used by the binding/task-keyed terminal writes, which
// settle the run by exact turn or by task rather than by run ID.
func (s *Service) settleFailedRunTaskForTask(ctx context.Context, taskID string) {
	run, err := s.store.GetLatestFailedRunByTask(ctx, taskID)
	if err != nil {
		s.logger.Warn("failed to load the failed run for task settlement",
			zap.String("task_id", taskID), zap.Error(err))
		return
	}
	s.enqueueFailedRunTaskSettlement(run)
}

// settleFailedRunTaskByID settles the generated task of one exact failed run.
func (s *Service) settleFailedRunTaskByID(ctx context.Context, runID string) {
	run, err := s.store.GetRun(ctx, runID)
	if err != nil {
		s.logger.Warn("failed to load the failed run for task settlement",
			zap.String("run_id", runID), zap.Error(err))
		return
	}
	s.enqueueFailedRunTaskSettlement(run)
}

// enqueueFailedRunTaskSettlement hands a failed run to the settlement worker.
// It never blocks and never runs the archive inline: failure settlement can
// happen under an orchestrator session lock, where stopping an execution or
// publishing a task event would re-enter that lock. A full queue drops the
// enqueue; startup reconciliation settles whatever is outstanding.
func (s *Service) enqueueFailedRunTaskSettlement(run *AutomationRun) {
	if run == nil || s.taskArchiver == nil || run.Status != RunStatusFailed || run.TaskID == "" {
		return
	}
	select {
	case s.failedSettleCh <- run:
	default:
		s.logger.Warn("failed-run task settlement queue is full; leaving the task to startup reconciliation",
			zap.String("run_id", run.ID), zap.String("task_id", run.TaskID))
	}
}

// failedRunTaskOriginIsHidden reports whether a task was created as a hidden
// automation run. A nil lookup, an unresolved task, or a visible
// automation_task all return false: a visible task is user work and is never
// archived by a run failure. Failing closed keeps ordinary tasks safe when the
// origin cannot be read.
func (s *Service) failedRunTaskOriginIsHidden(ctx context.Context, taskID string) bool {
	if s.taskOriginLookup == nil {
		return false
	}
	_, isAutomationRun, ok := s.taskOriginLookup.TaskWorkspaceAndAutomationOrigin(ctx, taskID)
	return ok && isAutomationRun
}

// ReconcileFailedRunTasks settles generated hidden tasks whose run already
// reached persisted terminal failed but whose archival did not complete — a
// crash between the two sides, or a settlement dropped during shutdown. It is
// idempotent and runs once at startup beside ReconcileOpenRuns. A read failure
// returns the error and touches no task, so a transient store problem is never
// mistaken for "nothing to settle".
func (s *Service) ReconcileFailedRunTasks(ctx context.Context) error {
	if s.taskArchiver == nil {
		return nil
	}
	runs, err := s.store.ListUnarchivedFailedRuns(ctx)
	if err != nil {
		return err
	}
	for _, run := range runs {
		s.settleFailedRunTask(ctx, run)
	}
	return nil
}

// startFailedRunTaskSettlementWorker launches the worker that drains the
// failed-run settlement queue and returns its cancel function and done channel,
// mirroring the managed-delivery worker in provider.go. The worker is stopped
// by cancelling its context; work still in flight is bounded by that context
// and any abandoned task is settled by the next startup pass.
func (s *Service) startFailedRunTaskSettlementWorker(ctx context.Context) (context.CancelFunc, chan struct{}) {
	workerCtx, cancel := context.WithCancel(ctx)
	done := make(chan struct{})
	go func() {
		defer close(done)
		for {
			select {
			case <-workerCtx.Done():
				return
			case run := <-s.failedSettleCh:
				s.settleFailedRunTask(workerCtx, run)
			}
		}
	}()
	return cancel, done
}

// errorsIsAnyOf reports whether err matches any of the given sentinels.
func errorsIsAnyOf(err error, sentinels ...error) bool {
	for _, sentinel := range sentinels {
		if errors.Is(err, sentinel) {
			return true
		}
	}
	return false
}
